<script setup lang="ts">
import {useAuth} from '../stores/auth'
import GovernanceSwitch from '../components/GovernanceSwitch.vue'
import ManagementTabs from '../components/ManagementTabs.vue'
import {formatDate} from '../ui/branding'
import {computed,onUnmounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
const route=useRoute(),router=useRouter(),auth=useAuth()
const tabs:Record<string,string>={samples:'样本管理',logs:'决策日志',statistics:'统计',configs:'路由规则'}
const view=computed(()=>route.path.split('/').pop()==='smart-route'?'samples':route.path.split('/').pop()!)
const sharedVector=ref('')
const configs=ref<any[]>([]),rows=ref<any[]>([]),models=ref<any[]>([]),groups=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref('')
const configId=ref<number|null>(null),page=ref(1),total=ref(0),status=ref(''),requestId=ref(''),virtual=ref(''),days=ref(7)
const sampleClass=ref(''),sampleQuery=ref(''),logQuery=ref(''),logSource=ref(''),logKind=ref(''),detailLoading=ref(false),bulkMode=ref('text'),bulkLabel=ref('simple'),bulkText=ref(''),bulkThreshold=ref<number|null>(null),bulkRemark=ref('')
const sources:Record<string,string>={local_rule:'本地规则（样本精确匹配）',vector:'向量相似度',model:'模型决策',fallback:'失败策略',error:'校验拒绝',legacy:'历史未记录'}
const reasons:Record<string,string>={ROUTE_MODEL_OTHER:'未匹配到业务目标，转兜底组',ROUTE_MODEL_LOW_CONFIDENCE:'决策置信度不足，转兜底组',ROUTE_MODEL_AUTH_FAILED:'决策服务鉴权失败，转兜底组',ROUTE_MODEL_INVALID:'决策结果无效，转兜底组',ROUTE_MODEL_UNAVAILABLE:'决策服务连接失败或超时，转兜底组',ROUTE_NO_SAMPLES:'没有可用的已构建样本',ROUTE_LOW_SIMILARITY:'未达到生效阈值',ROUTE_AMBIGUOUS:'分类置信差不足',ROUTE_CHANGED:'配置在决策期间发生变化',ROUTE_DISABLED:'路由规则未启用',ROUTE_GROUP_EMPTY:'目标模型组无可用映射'}
function reasonText(code:string|null){return code?reasons[code]||code:'达到当前分类阈值'}
function score(value:number|null|undefined){return value==null?'未记录':(value*100).toFixed(1)+'%'}
async function showDetail(row:any){detailLoading.value=true;try{detail.value=(await api.get('/admin/smart-route/logs/'+row.id)).data.data}catch(e){ElMessage.error(message(e))}finally{detailLoading.value=false}}
function previewAdd(){if(!previewResult.value?.classification)return;sampleOpen();sample.prompt=previewResult.value.normalized_text;sample.classification=previewResult.value.classification;previewDialog.value=false}
async function bulkSave(){if(bulkMode.value==='csv'){await importCSV();return}const prompts=bulkText.value.split(/\r?\n/).map(p=>p.trim().normalize('NFC')).filter(Boolean);if(!prompts.length||prompts.length>500){ElMessage.error('请输入1至500条样本，每行一条');return}if(new Set(prompts).size!==prompts.length){ElMessage.error('本批次存在重复样本，请去重后再提交');return}saving.value=true;try{const d=(await api.post('/admin/smart-route/samples',{config_id:configId.value,samples:prompts.map(prompt=>({prompt,classification:bulkLabel.value,similarity_threshold:bulkThreshold.value,remark:bulkRemark.value,build_vector:buildCSV.value}))})).data.data;importDialog.value=false;await load();ElMessage.success('已新增 '+d.ids.length+' 条样本，已加入构建队列 '+d.queued+' 条')}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
const logTarget=ref('')
const targetNames=computed(()=>[...new Set(configs.value.flatMap(c=>(c.decision_targets||[]).map((t:any)=>t.name)).concat('兜底'))])
const logClass=ref(''),logStatus=ref(''),logOperation=ref(''),logModel=ref(''),distribution=ref('classification')
const range=ref<[Date,Date]|null>(null),statsRange=ref<any>(null),dialog=ref(false),sampleDialog=ref(false),importDialog=ref(false),detail=ref<any>(null)
const editing=ref<number|null>(null),sampleEditing=ref<number|null>(null),csv=ref('prompt,classification\n简单问候,simple\n复杂推理,complex')
const blank=()=>({decision_provider:'typesafe',decision_service_url:'',decision_workspace:'',decision_region:'cn-beijing',route_mode:'vector',decision_api_key:'',clear_decision_key:false,decision_timeout:15,decision_threshold:.5,decision_fallback_group:null as number|null,decision_targets:[] as {name:string;model_group_id:number|null;description:string;exclusion:string}[],virtual_model:'AI-Auto',embedding_model:'',simple_model_group:0,complex_model_group:0,top_k:5,similarity_threshold:.75,confidence_gap:.1,fallback:'error',status:'disabled',expected_updated_at:null as string|null})
const sampleTable=ref<any>(),selected=ref<any[]>([]),building=ref(false),buildCSV=ref(false)
const currentConfig=computed(()=>configs.value.find(c=>c.id===configId.value))
const expectedClass=ref('')
const previewChoices=computed(()=>currentConfig.value?.route_mode==='model'?(currentConfig.value.decision_targets||[]).map((t:any)=>({label:t.name,value:t.name})).concat([{label:'兜底',value:'兜底'}]):[{label:'简单任务',value:'simple'},{label:'复杂任务',value:'complex'}])
const decisionProviderName=(m:string)=>m==='decision-model-preview'?'阿里云百炼':'TypeSafe'
async function testConnection(row:any){try{await api.post('/admin/smart-route/configs/'+row.id+'/test-connection');ElMessage.success('连接及鉴权检查通过（不验证生成能力）')}catch(e){ElMessage.error(message(e))}}
const previewDialog=ref(false),previewText=ref(''),previewConsent=ref(false),previewLoading=ref(false),previewResult=ref<any>(null)
function previewOpen(){expectedClass.value='';previewText.value='';previewConsent.value=false;previewResult.value=null;previewDialog.value=true}
async function previewRoute(){if(!configId.value||!previewConsent.value)return;previewLoading.value=true;previewResult.value=null;try{previewResult.value=(await api.post('/admin/smart-route/configs/'+configId.value+'/preview',{prompt:previewText.value})).data.data}catch(e){ElMessage.error(message(e))}finally{previewLoading.value=false}}
const form=reactive(blank()),sample=reactive({prompt:'',classification:'simple',similarity_threshold:null as number|null,remark:'',build_vector:false,expected_revision:null as number|null})
const editorMode=computed(()=>form.route_mode)
watch(()=>form.route_mode,mode=>{if(mode==='vector'&&sharedVector.value)form.embedding_model=sharedVector.value})
watch(()=>form.decision_provider,()=>{form.decision_api_key='';form.clear_decision_key=false})
const modelTesting=ref(false),modelTestResult=ref<any>(null)
let testController:AbortController|undefined,testGeneration=0
function resetModelTest(){testGeneration++;testController?.abort();modelTesting.value=false;modelTestResult.value=null}
watch(()=>[dialog.value,editing.value,form.route_mode,form.decision_provider,form.decision_service_url,form.decision_workspace,form.decision_region,form.decision_api_key,form.clear_decision_key,form.decision_timeout],resetModelTest,{flush:'sync'})
async function testDecisionModel(){
 const version=testGeneration
 try{await ElMessageBox.confirm('将向所选供应商发送固定的“你好”及两个测试类别，验证真实决策响应，可能产生少量费用；不会保存配置或调用目标模型。','测试决策模型',{confirmButtonText:'开始测试',cancelButtonText:'取消'})}catch{return}
 if(version!==testGeneration)return
 const controller=new AbortController();testController=controller;modelTesting.value=true;modelTestResult.value=null
 try{const data=(await api.post('/admin/smart-route/test-model',{config_id:editing.value,expected_updated_at:form.expected_updated_at,decision_service_url:form.decision_service_url,decision_provider:form.decision_provider,decision_workspace:form.decision_workspace,decision_region:form.decision_region,decision_api_key:form.decision_api_key||null,decision_timeout:form.decision_timeout,consent:true},{signal:controller.signal,timeout:(form.decision_timeout+10)*1000})).data.data;if(version===testGeneration)modelTestResult.value=data}
 catch(e){if(version===testGeneration)modelTestResult.value={available:false,message:message(e)}}
 finally{if(version===testGeneration)modelTesting.value=false}
}

const labels:Record<string,string>={not_built:'未构建',simple:'简单任务',complex:'复杂任务',classified:'已分类',fallback:'降级',failed:'失败',pending:'待向量化',processing:'处理中',ready:'就绪',stale:'已失效',error:'报错'}
function vectorState(row:any){
 const status=row.vector_status==='pending'&&!row.vector_requested?'not_built':row.vector_status
 const states:Record<string,{label:string;tone:'success'|'warning'|'danger'|'info'|'primary';hint:string}>={
  not_built:{label:'未构建',tone:'info',hint:'尚未生成向量，构建后可用于分类'},
  pending:{label:'排队中',tone:'primary',hint:'已提交任务，等待可用并发名额'},
  processing:{label:'构建中',tone:'primary',hint:'正在生成向量，请稍候'},
  ready:{label:'已就绪',tone:'success',hint:'向量已就绪，可参与分类检索'},
  stale:{label:'待重建',tone:'warning',hint:'配置或样本已变化，请重新构建向量'},
  failed:{label:'构建失败',tone:'danger',hint:({UPSTREAM_TIMEOUT:'上游响应超时，可稍后重试',ROUTE_JOB_BUSY:'并发名额不足，可稍后重试',UPSTREAM_AUTH_FAILED:'上游鉴权失败，请检查账号',ROUTE_PROVIDER_CHANGED:'账号配置已变化，请重新构建',ROUTE_JOB_STALE:'样本版本已变化，请重新构建',VECTOR_CONFIG_CHANGED:'向量服务已变化，请重新构建'} as Record<string,string>)[row.vector_error]||'向量未能生成，请查看调用日志后重试'}
 }
 return {...(states[status]||{label:'未知状态',tone:'info' as const,hint:'请刷新后查看最新状态'}),active:status==='processing'}
}
function groupName(id:number){return groups.value.find(g=>g.id===id)?.name||'#'+id}
function params(){const end=range.value?.[1]||new Date(),start=range.value?.[0]||new Date(end.getTime()-days.value*86400000);return {start:start.toISOString(),end:end.toISOString(),virtual_model:virtual.value||undefined}}
let generation=0
async function load(){const mine=++generation;error.value='';loading.value=true;try{
  const listing=await api.get('/admin/smart-route/configs');const c=listing.data.data
  if(mine!==generation)return;sharedVector.value=listing.data.meta?.shared_vector_model||'';configs.value=c
  if(configId.value&&!c.some((x:any)=>x.id===configId.value))configId.value=null;if(!configId.value&&c.length)configId.value=c[0].id
  if(view.value==='configs'){
    rows.value=c
    const [m,g]=await Promise.all([api.get('/admin/logical-models'),api.get('/admin/model-group-options')])
    if(mine!==generation)return;models.value=m.data.data.filter((x:any)=>x.model_type==='embedding');groups.value=g.data.data
    rows.value=c
  }else if(view.value==='samples'){
    const d=configId.value?(await api.get('/admin/smart-route/samples',{params:{config_id:configId.value,page:page.value,vector_status:status.value||undefined,classification:sampleClass.value||undefined,q:sampleQuery.value||undefined}})).data.data:{items:[],total:0}
    if(mine!==generation)return;rows.value=d.items;total.value=d.total;if(page.value>1&&!d.items.length){page.value=Math.max(1,Math.ceil(d.total/20));await load()}
  }else if(view.value==='logs'){
    const d=(await api.get('/admin/smart-route/logs',{params:{...params(),request_id:requestId.value||undefined,page:page.value,
      q:logQuery.value||undefined,source:logSource.value||undefined,request_kind:logKind.value||undefined,classification:logClass.value||undefined,status:logStatus.value||undefined,operation:logOperation.value||undefined,selected_model:logModel.value||undefined,decision_target:logTarget.value||undefined}})).data.data
    if(mine!==generation)return;rows.value=d.items;total.value=d.total;if(page.value>1&&!d.items.length){page.value=Math.max(1,Math.ceil(d.total/20));await load()}
  }else{
    const d=(await api.get('/admin/smart-route/statistics',{params:params()})).data.data
    if(mine!==generation)return;rows.value=d.items;statsRange.value=d
  }
}catch(e){if(mine===generation)error.value=message(e)}finally{if(mine===generation)loading.value=false}}
function open(row?:any){editing.value=row?.id??null;Object.assign(form,blank(),{embedding_model:sharedVector.value});if(row){for(const key of Object.keys(blank()))if(!['expected_updated_at','decision_api_key','clear_decision_key'].includes(key)&&(row[key]!==undefined))(form as any)[key]=JSON.parse(JSON.stringify(row[key]));form.expected_updated_at=row.updated_at}if(editorMode.value==='vector'&&sharedVector.value)form.embedding_model=sharedVector.value;dialog.value=true}
async function save(){saving.value=true;try{await api[editing.value?'put':'post']('/admin/smart-route/configs'+(editing.value?'/'+editing.value:''),{...form,embedding_model:form.embedding_model||null,simple_model_group:form.simple_model_group||null,complex_model_group:form.complex_model_group||null,decision_api_key:form.decision_api_key||null});form.decision_api_key='';dialog.value=false;await load();ElMessage.success('路由规则已保存')}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('删除规则及其所有样本，历史决策保留。已加入模型组的虚拟模型需先移除关联。','删除 '+row.virtual_model,{type:'warning'});await api.delete('/admin/smart-route/configs/'+row.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
function sampleOpen(row?:any){sampleEditing.value=row?.id??null;Object.assign(sample,{prompt:row?.prompt||'',classification:row?.classification||'simple',similarity_threshold:row?.similarity_threshold??null,remark:row?.remark||'',build_vector:false,expected_revision:row?.revision??null});sampleDialog.value=true}
async function sampleSave(){if(!configId.value)return;saving.value=true;try{
  if(sampleEditing.value)await api.put('/admin/smart-route/samples/'+sampleEditing.value,sample)
  else await api.post('/admin/smart-route/samples',{config_id:configId.value,samples:[sample]})
  sampleDialog.value=false;await load();ElMessage.success(sample.build_vector?'样本已保存并加入构建队列':'样本已保存，尚未构建向量')
}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function retry(row:any){try{await api.post('/admin/smart-route/samples/'+row.id+'/vectorize');await load();ElMessage.success('已加入向量化队列')}catch(e){ElMessage.error(message(e))}}
async function sampleRemove(row:any){try{await ElMessageBox.confirm('删除该样本及其向量？','删除样本',{type:'warning'});await api.delete('/admin/smart-route/samples/'+row.id);selected.value=[];sampleTable.value?.clearSelection();await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
async function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;try{if(f.size>2*1024*1024)throw new Error();csv.value=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer())}catch{ElMessage.error('请选择不超过2MB的UTF-8 CSV文件')}finally{(event.target as HTMLInputElement).value=''}}
async function importCSV(){saving.value=true;try{const d=(await api.post('/admin/smart-route/samples/import',{config_id:configId.value,content:csv.value,build_vector:buildCSV.value})).data.data;importDialog.value=false;await load();ElMessage.success('已导入 '+d.ids.length+' 条样本，已加入构建队列 '+d.queued+' 条')}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function buildSelected(all:boolean){if(!configId.value)return;try{await ElMessageBox.confirm('构建会通过已配置的向量服务发起请求，可能产生用量。',all?'构建全部样本向量':'构建选中样本向量',{confirmButtonText:'构建',cancelButtonText:'取消'});building.value=true;const result=(await api.post('/admin/smart-route/samples/vectorize',{config_id:configId.value,all_samples:all,sample_ids:all?[]:selected.value.map(row=>row.id)})).data.data;ElMessage.success('已加入构建队列 '+result.queued+' 条；已排队或构建中的样本不重复提交');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}finally{building.value=false}}
watch([configId,status,sampleClass,sampleQuery],()=>{selected.value=[];sampleTable.value?.clearSelection()})
function resetFilters(){status.value='';sampleClass.value='';sampleQuery.value='';requestId.value='';virtual.value='';logQuery.value='';logSource.value='';logKind.value='';logTarget.value='';logClass.value='';logStatus.value='';logOperation.value='';logModel.value='';range.value=null;days.value=7;page.value=1;load()}
const summary=computed(()=>statsRange.value?.summary||{})
const distributionRows=computed(()=>statsRange.value?.distributions?.[distribution.value]||[])
function distributionName(name:string|null){if(name===null)return distribution.value==='model'?'未关联模型':'未分类';if(distribution.value==='source')return sources[name]||name;return labels[name]||({'unknown':'未上报用量'} as Record<string,string>)[name]||name}
watch(()=>route.fullPath,()=>{configId.value=route.query.config_id?Number(route.query.config_id):null;requestId.value=String(route.query.request_id||'');page.value=1;rows.value=[];load()},{immediate:true})
const timer=setInterval(()=>{if(view.value==='samples'&&!saving.value&&!loading.value&&!sampleDialog.value&&!importDialog.value&&!previewDialog.value&&!building.value&&!selected.value.length&&!document.hidden)load()},5000)
onUnmounted(()=>{clearInterval(timer);generation++;resetModelTest()})
</script>
<template><div class="module-page smart-route-page">
<PageHeader title="智能路由"/>

<div class="panel module-panel routing-settings">
<GovernanceSwitch v-if="auth.user?.role==='super_admin'" embedded field="smart_route_enabled" title="智能路由总开关" description="关闭后所有虚拟路由模型停止提供服务，规则与样本保留。总开关控制整体服务，各规则的启停状态独立保存。" @changed="load"/>

</div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div class="panel module-panel">
<ManagementTabs :value="view" :items="tabs" @change="router.push('/admin/smart-route/'+$event)"/>

<div class="smart-route-content">
<div class="toolbar module-filters">
<template v-if="view==='configs'"><h2>路由规则</h2></template>
<template v-else-if="view==='samples'">
<el-select v-model="configId" placeholder="选择路由规则" style="width:220px" @change="page=1;load()"><el-option v-for="c in configs" :key="c.id" :label="c.virtual_model" :value="c.id"/></el-select>
<el-select v-model="status" placeholder="全部向量状态" clearable style="width:160px" @change="page=1;load()"><el-option v-for="s in ['not_built','pending','processing','ready','failed','stale']" :key="s" :label="labels[s]" :value="s"/></el-select>
<el-select v-model="sampleClass" clearable placeholder="全部标签" style="width:140px" @change="page=1;load()"><el-option label="简单任务" value="simple"/><el-option label="复杂任务" value="complex"/></el-select><el-input v-model="sampleQuery" clearable placeholder="搜索样本文本 / 备注" style="width:210px" @keyup.enter="page=1;load()"/>
</template>
<template v-else>
<el-select v-model="virtual" clearable filterable allow-create placeholder="全部虚拟模型" style="width:190px"><el-option v-for="c in configs" :key="c.id" :label="c.virtual_model" :value="c.virtual_model"/></el-select>
<el-input v-if="view==='logs'" v-model="requestId" placeholder="Request ID 精确查询" clearable style="width:260px"/>
<template v-if="view==='logs'">
<el-input v-model="logQuery" clearable placeholder="搜索 Request ID / 模型 / 文本" style="width:280px" @keyup.enter="page=1;load()"/>
<el-select v-model="logTarget" clearable placeholder="全部路由目标"><el-option v-for="target in targetNames" :key="target" :label="target" :value="target"/></el-select><el-select v-model="logSource" clearable placeholder="全部决策来源" style="width:210px"><el-option v-for="(label,value) in sources" :key="value" :value="value" :label="label"/></el-select>
<el-select v-model="logKind" clearable placeholder="全部请求类型" style="width:160px"><el-option label="真实请求" value="real"/><el-option label="决策预览" value="preview"/></el-select>
<el-select v-model="logClass" clearable placeholder="全部分类" style="width:140px"><el-option v-for="c in ['simple','complex','unclassified']" :key="c" :value="c" :label="labels[c]||'未分类'"/></el-select>
<el-select v-model="logStatus" clearable placeholder="全部决策状态" style="width:160px"><el-option v-for="s in ['classified','fallback','failed']" :key="s" :value="s" :label="labels[s]"/></el-select>
<el-input v-model="logOperation" placeholder="请求类型，如chat" clearable style="width:170px"/>
<el-input v-model="logModel" placeholder="选中逻辑模型" clearable style="width:190px"/>
</template>
<el-select v-model="days" style="width:140px" @change="range=null"><el-option :value="1" label="最近24小时"/><el-option :value="7" label="最近7天"/><el-option :value="30" label="最近30天"/></el-select>
<el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间"/>
</template>
<el-button type="primary" :loading="loading" @click="page=1;load()">{{view==='configs'||view==='samples'?'刷新':'查询'}}</el-button><el-button v-if="view!=='configs'" @click="resetFilters">重置</el-button>
</div>
<el-alert v-if="view==='samples'&&currentConfig?.route_mode==='model'" type="info" :closable="false" title="当前为模型决策模式，不使用样本；原样本保留，编辑或构建需切回本地 / 向量模式。" style="margin-bottom:16px"/><div v-if="view==='configs'||view==='samples'" class="toolbar module-actions"><el-button v-if="view==='configs'" type="primary" @click="open()">新增路由规则</el-button><template v-else><el-button type="primary" :disabled="!configId||currentConfig?.route_mode==='model'" @click="sampleOpen()">新增样本</el-button><el-button :disabled="!configId||currentConfig?.route_mode==='model'" @click="bulkText='';bulkMode='text';bulkThreshold=null;bulkRemark='';bulkLabel='simple';buildCSV=false;importDialog=true">批量添加</el-button><el-button :disabled="!selected.length||building||currentConfig?.route_mode==='model'" :loading="building" @click="buildSelected(false)">构建选中向量</el-button><el-button :disabled="!configId||!total||building||currentConfig?.route_mode==='model'" :loading="building" @click="buildSelected(true)">构建全部向量</el-button>
<el-button :disabled="!configId" @click="previewOpen">决策预览</el-button></template></div>
<el-table v-if="view==='configs'" :data="rows" v-loading="loading" empty-text="暂无规则，请新增路由规则并选择路由模式">
<el-table-column prop="virtual_model" label="虚拟模型" min-width="140"/><el-table-column label="路由模式 / 决策模型" min-width="200"><template #default="s">{{s.row.route_mode==='model'?'模型决策':'本地 / 向量'}}<br/>{{s.row.route_mode==='model'?(s.row.decision_provider==='aliyun'?'阿里云 / decision-model-preview':'TypeSafe / jev-latest'):s.row.embedding_model}}</template></el-table-column>
<el-table-column label="样本就绪" min-width="200"><template #default="s"><template v-if="s.row.route_mode==='vector'"><el-tag :type="s.row.sample_summary?.ready?'success':'warning'">{{s.row.sample_summary?.ready??0}} / {{s.row.sample_summary?.total??0}} 就绪</el-tag><p v-if="!s.row.sample_summary?.ready" class="field-help">无就绪样本；未命中时转简单任务组。请添加并构建样本。</p></template><span v-else class="muted">模型决策不使用样本</span></template></el-table-column>
<el-table-column label="路由目标" min-width="200"><template #default="s"><template v-if="s.row.route_mode==='model'">{{s.row.decision_targets.map((t:any)=>t.name).join(' / ')}}</template><template v-else>{{groupName(s.row.simple_model_group)}} / {{groupName(s.row.complex_model_group)}}</template></template></el-table-column>
<el-table-column label="决策参数" min-width="170"><template #default="s"><template v-if="s.row.route_mode==='model'">置信度 ≥ {{s.row.decision_threshold}} · {{s.row.decision_timeout}} 秒</template><template v-else>TopK {{s.row.top_k}} · 阈值 {{s.row.similarity_threshold}} · 差值 {{s.row.confidence_gap}}</template></template></el-table-column>
<el-table-column label="失败策略" width="110"><template #default="s">{{s.row.route_mode==='model'?'转 '+groupName(s.row.decision_fallback_group):labels[s.row.fallback]}}</template></el-table-column>
<el-table-column label="状态" width="80"><template #default="s"><el-tag :type="s.row.status==='enabled'?'success':'info'">{{s.row.status==='enabled'?'启用':'禁用'}}</el-tag></template></el-table-column>
<el-table-column label="操作" min-width="280" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="primary" @click="configId=s.row.id;previewOpen()">决策预览</el-button><el-button v-if="s.row.route_mode!=='model'" link @click="router.push({path:'/admin/smart-route/samples',query:{config_id:s.row.id}})">管理样本</el-button><el-button v-if="s.row.route_mode==='model'&&s.row.decision_provider==='typesafe'" link @click="testConnection(s.row)">测试连接</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column>
<template #empty><EmptyState title="暂无路由规则" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table>
<template v-else-if="view==='samples'">
<p class="muted module-note">空闲时每5秒刷新，编辑或选择样本时暂停。只使用就绪且版本匹配的向量；更改Embedding模型后旧样本向量失效，需手动重建，保存不会触发调用。管理员样本向量化使用全局和账号并发，实际用量在调用日志中独立记录。</p>
<el-table :data="rows" v-loading="loading" ref="sampleTable" row-key="id" @selection-change="selected=$event" empty-text="暂无样本"><el-table-column type="selection" width="45" :reserve-selection="true"/><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="prompt" label="样本文本" min-width="240" show-overflow-tooltip/><el-table-column label="单样本阈值" width="120"><template #default="s">{{s.row.similarity_threshold??'继承规则'}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="140" show-overflow-tooltip/>
<el-table-column label="类别 / 目标组" min-width="150"><template #default="s">{{labels[s.row.classification]}} · #{{s.row.model_group_id}}</template></el-table-column>
<el-table-column label="向量状态" min-width="190"><template #default="s"><div class="vector-state"><el-tooltip :content="vectorState(s.row).hint" placement="top"><el-tag :type="vectorState(s.row).tone" size="small" effect="light" round class="vector-state-tag"><span class="vector-state-dot" :class="{'is-active':vectorState(s.row).active}" aria-hidden="true"/>{{vectorState(s.row).label}}</el-tag></el-tooltip><el-tooltip v-if="s.row.vector_error" :content="vectorState(s.row).hint+'（'+s.row.vector_error+'）'" placement="top"><span class="vector-state-error">{{vectorState(s.row).hint}}</span></el-tooltip><router-link v-if="s.row.vector_request_id" :to="'/admin/call-logs/'+s.row.vector_request_id" class="vector-state-log" :aria-label="'查看样本 '+s.row.id+' 的向量调用日志'">查看调用日志 <span aria-hidden="true">→</span></router-link></div></template></el-table-column>
<el-table-column label="操作" min-width="210" fixed="right"><template #default="s"><el-button link :disabled="currentConfig?.route_mode==='model'" @click="sampleOpen(s.row)">编辑</el-button><el-button link type="primary" :disabled="currentConfig?.route_mode==='model'||s.row.vector_status==='processing'||s.row.vector_status==='pending'&&s.row.vector_requested" @click="retry(s.row)">重新向量化</el-button><el-button link type="danger" @click="sampleRemove(s.row)">删除</el-button></template></el-table-column><template #empty><EmptyState title="暂无样本" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table>
</template>
<el-table v-else-if="view==='logs'" :data="rows" v-loading="loading" empty-text="所选范围暂无路由决策">
<el-table-column label="Request ID" min-width="230"><template #default="s"><el-button link type="primary" @click="showDetail(s.row)">{{s.row.request_id}}</el-button></template></el-table-column><el-table-column prop="virtual_model" label="虚拟模型" min-width="130"/><el-table-column label="决策来源" min-width="150"><template #default="s">{{sources[s.row.source]||'历史未记录'}}</template></el-table-column><el-table-column label="请求类型" width="100"><template #default="s">{{s.row.request_kind==='preview'?'决策预览':'真实请求'}}</template></el-table-column><el-table-column prop="text_excerpt" label="请求文本" min-width="200" show-overflow-tooltip/>
<el-table-column label="结果" width="110"><template #default="s">{{labels[s.row.status]}}</template></el-table-column><el-table-column label="分类 / 目标" min-width="130"><template #default="s">{{s.row.decision_target||labels[s.row.classification]||'—'}}</template></el-table-column>
<el-table-column label="置信度 / 分类差" width="140"><template #default="s">{{s.row.confidence==null?'未记录':s.row.source==='model'?score(s.row.confidence):s.row.confidence.toFixed(4)}}</template></el-table-column><el-table-column prop="selected_group_name" label="选中模型组" min-width="140"/><el-table-column label="相似度" width="100"><template #default="s">{{s.row.similarity?.toFixed(4)??'—'}}</template></el-table-column><el-table-column prop="elapsed_ms" label="决策耗时 ms" width="130"/>
<el-table-column prop="operation" label="调用操作" width="110"/><el-table-column prop="selected_model" label="选中模型" min-width="160"/>
<el-table-column label="时间" min-width="160"><template #default="s">{{formatDate(s.row.created_at)}}</template></el-table-column><template #empty><EmptyState title="所选范围暂无路由决策" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table>
<template v-else>
<div class="route-cards"><div>决策数<strong>{{summary.decisions??0}}</strong></div><div>真实请求数<strong>{{summary.real_requests??0}}</strong></div><div>失败数<strong>{{summary.failures??0}}</strong></div><div>总 Token<strong>{{summary.total_tokens??'—'}}</strong></div><div>平均 Token<strong>{{summary.average_tokens?.toFixed(2)??'—'}}</strong></div><div>累计决策耗时 ms<strong>{{summary.elapsed_ms?.toFixed(2)??0}}</strong></div></div>
<p class="muted">{{statsRange?.metric_scope}}。预览 {{summary.previews??0}} 次。仅统计父推理请求的Token；未上报用量不估算，已上报 {{summary.usage_count??0}} 条。</p>
<el-radio-group v-model="distribution" aria-label="统计分布维度"><el-radio-button value="classification">按标签分布</el-radio-button><el-radio-button value="source">按来源分布</el-radio-button><el-radio-button value="model">按模型分布</el-radio-button><el-radio-button value="tokens">按总 Token 分布</el-radio-button></el-radio-group>
<el-table :data="distributionRows" empty-text="暂无分布数据" style="margin:16px 0"><el-table-column label="维度"><template #default="s">{{distributionName(s.row.name)}}</template></el-table-column><el-table-column prop="decisions" label="决策数"/><el-table-column prop="real_requests" label="真实请求数"/><el-table-column label="占比"><template #default="s">{{summary.decisions?(s.row.decisions/summary.decisions*100).toFixed(1)+'%':'—'}}</template></el-table-column><el-table-column label="总 Token"><template #default="s">{{s.row.total_tokens??'未上报'}} · {{s.row.usage_count}} 条已上报</template></el-table-column></el-table>
<el-table :data="rows" v-loading="loading" empty-text="所选范围暂无路由统计"><el-table-column label="分类" min-width="130"><template #default="s">{{s.row.decision_target||labels[s.row.classification]||s.row.classification||'未分类'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s">{{labels[s.row.status]}}</template></el-table-column><el-table-column prop="selected_group_name" label="模型组" min-width="140"/><el-table-column prop="requests" label="请求数" width="90"/><el-table-column label="平均相似度" width="130"><template #default="s">{{s.row.similarity?.toFixed(4)??'—'}}</template></el-table-column><el-table-column label="平均决策耗时 ms" width="160"><template #default="s">{{s.row.elapsed_ms?.toFixed(2)??'—'}}</template></el-table-column><el-table-column label="已上报Token" width="140"><template #default="s">{{s.row.usage_count?s.row.total_tokens:'—'}} · {{s.row.usage_count}}条</template></el-table-column><template #empty><EmptyState title="所选范围暂无路由统计" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table>
<el-button v-if="virtual&&statsRange" link type="primary" @click="router.push({path:'/admin/usage',query:{model:virtual,start:statsRange.start,end:statsRange.end}})">查看该虚拟模型对应的推理用量</el-button>
</template>
<el-pagination v-if="view==='samples'||view==='logs'" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" style="margin-top:24px" @current-change="load"/>
</div>
</div>
<el-dialog v-model="previewDialog" title="决策预览" width="720px" :close-on-click-modal="!previewLoading"><el-input v-model="previewText" type="textarea" :rows="6" maxlength="16000" show-word-limit placeholder="输入需要分类的请求文本" :disabled="previewLoading"/><el-alert v-if="currentConfig?.route_mode==='model'" type="info" :closable="false" :title="'当前使用模型决策：'+decisionProviderName(currentConfig.decision_provider==='aliyun'?'decision-model-preview':'jev-latest')"/><p class="muted">预览与真实请求使用相同规则和已就绪样本，记录预览决策；不执行最终文本生成、不自动保存样本。当前模式使用向量或所选供应商的决策服务，用量独立记录在调用日志。</p><el-form label-position="top"><el-form-item label="预期分类（可选）"><el-select v-model="expectedClass" clearable placeholder="不设置预期" :disabled="previewLoading"><el-option v-for="choice in previewChoices" :key="choice.value" :label="choice.label" :value="choice.value"/></el-select></el-form-item></el-form><el-checkbox v-model="previewConsent" :disabled="previewLoading">允许当前模式必要的向量 / 外部模型决策请求，可能产生用量</el-checkbox><template v-if="previewResult"><el-alert v-if="expectedClass" :type="(previewResult.decision_target||previewResult.classification)===expectedClass?'success':'warning'" :closable="false" :title="(previewResult.decision_target||previewResult.classification)===expectedClass?'与预期分类一致':'与预期不一致，请检查当前模式的分类依据'" style="margin-top:16px"/><p>{{labels[previewResult.status]}} · {{previewResult.decision_target||labels[previewResult.classification]||'未分类'}} · {{previewResult.selected_group_name||'未选择目标组'}}</p><p v-if="previewResult.source!=='model'">最高相似度 {{score(previewResult.similarity)}} · 分类置信差 {{score(previewResult.confidence)}} · {{previewResult.elapsed_ms}} ms</p><p v-if="previewResult.source==='model'">{{decisionProviderName(previewResult.decision_model)}} / {{previewResult.decision_model}} · 置信度 {{score(previewResult.confidence)}} · {{previewResult.elapsed_ms}} ms</p><p class="muted">{{sources[previewResult.source]}} · {{reasonText(previewResult.reason)}} · 候选模型 {{previewResult.candidate_models.join(' / ')||'—'}}</p><p><router-link class="route-link" :to="{path:'/admin/smart-route/logs',query:{request_id:previewResult.request_id}}">查看本次预览决策详情 →</router-link></p><el-table v-if="previewResult.source!=='model'" :data="previewResult.evidence" empty-text="无有效命中样本"><el-table-column prop="sample_id" label="样本ID"/><el-table-column label="标签"><template #default="s">{{labels[s.row.classification]}}</template></el-table-column><el-table-column label="相似度"><template #default="s">{{s.row.similarity.toFixed(6)}}</template></el-table-column><el-table-column label="生效阈值"><template #default="s">{{score(s.row.effective_threshold??s.row.similarity_threshold)}}</template></el-table-column></el-table><el-table v-if="previewResult.source==='model'" :data="previewResult.evidence"><el-table-column prop="target" label="路由目标" min-width="160"/><el-table-column label="模型选择" width="100"><template #default="s">{{s.row.selected===true?'选中':s.row.selected===false?'—':'未记录'}}</template></el-table-column><el-table-column label="概率"><template #default="s">{{score(s.row.probability)}}</template></el-table-column></el-table><router-link v-if="previewResult.decision_request_id" :to="'/admin/call-logs/'+previewResult.decision_request_id">查看决策子调用 →</router-link><router-link v-if="previewResult.embedding_request_id" :to="'/admin/call-logs/'+previewResult.embedding_request_id" class="route-link">查看向量请求用量</router-link></template><template #footer><el-button v-if="previewResult?.classification && previewResult.source!=='model'" type="success" :disabled="previewResult.source==='local_rule'" @click="previewAdd">{{previewResult.source==='local_rule'?'已有匹配样本':'添加为样本'}}</el-button><el-button @click="previewDialog=false" :disabled="previewLoading">关闭</el-button><el-button type="primary" :loading="previewLoading" :disabled="!previewConsent||!previewText.trim()" @click="previewRoute">预览</el-button></template></el-dialog>
<el-drawer v-model="dialog" :title="editing?'编辑路由规则':'新增路由规则'" size="min(860px, 100%)"><el-form label-width="120px">
<el-form-item label="虚拟模型"><el-input v-model="form.virtual_model" :disabled="!!editing" maxlength="100"/></el-form-item>
<el-form-item label="路由模式"><el-radio-group v-model="form.route_mode"><el-radio-button value="vector">本地 / 向量</el-radio-button><el-radio-button value="model">模型决策</el-radio-button></el-radio-group><p class="field-help">每条路由规则独立设置模式，只影响当前虚拟模型；切换保留另一模式的参数、密钥和样本。</p></el-form-item><template v-if="editorMode==='vector'"><el-form-item label="Embedding模型"><el-select v-model="form.embedding_model" :disabled="!!sharedVector" filterable style="width:100%"><el-option v-for="m in models" :key="m.name" :value="m.name" :label="m.name"/></el-select><p v-if="sharedVector" class="muted">使用系统设置中的共享向量模型；更换服务需在系统设置统一操作。</p></el-form-item>
<el-form-item v-for="key in ['simple_model_group','complex_model_group']" :key="key" :label="key==='simple_model_group'?'简单任务组':'复杂任务组'"><el-select v-model="(form as any)[key]" filterable style="width:100%"><el-option v-for="g in groups" :key="g.id" :value="g.id" :label="g.name" :disabled="g.status!=='enabled'||!['text','multimodal'].includes(g.protocol_type||'text')"/></el-select></el-form-item>
<el-divider content-position="left">判定参数</el-divider><el-form-item label="参数起点"><el-button @click="form.top_k=5;form.similarity_threshold=.75;form.confidence_gap=.1">填入默认参数</el-button><p class="field-help">仅填入草稿，不自动保存。请先用典型问题做决策预览，再调整阈值。</p></el-form-item><el-form-item label="Top K"><el-input-number v-model="form.top_k" :min="1" :max="50" :precision="0"/><p class="field-help">检索最相近的样本数量，范围 1–50。</p></el-form-item><el-form-item label="相似度阈值"><el-input-number v-model="form.similarity_threshold" :min="0" :max="1" :step=".01" :precision="2"/><p class="field-help">范围 0–1，越高越严格。单样本阈值留空时继承此值。</p></el-form-item><el-form-item label="分类置信差"><el-input-number v-model="form.confidence_gap" :min="0" :max="1" :step=".01" :precision="2"/><p class="field-help">最高类别与另一类别的相似度差，不是概率。差值不足时转简单任务组。</p></el-form-item>
<el-form-item label="失败策略"><el-select v-model="form.fallback"><el-option label="返回错误" value="error"/><el-option label="转简单任务组" value="simple"/><el-option label="转复杂任务组" value="complex"/></el-select></el-form-item></template><template v-else><el-form-item label="决策供应商"><el-select v-model="form.decision_provider"><el-option label="TypeSafe / jev-latest" value="typesafe"/><el-option label="阿里云百炼 / decision-model-preview" value="aliyun"/></el-select></el-form-item><template v-if="form.decision_provider==='aliyun'"><el-form-item label="服务地址"><el-input v-model="form.decision_service_url" maxlength="2048" placeholder="https://服务域名/compatible-mode/v1/systemone"/><p class="field-help">填写完整 HTTPS 决策接口地址（包含 /systemone）；测试与实际决策均使用此地址。</p></el-form-item></template><el-alert :title="form.decision_provider==='aliyun'?'阿里云百炼 / decision-model-preview':'TypeSafe / jev-latest'" type="info" :closable="false" show-icon>决策会将问题文本、目标名称和适用 / 排除说明发送至所选供应商，产生独立用量。密钥加密保存，留空保留原密钥；仅转发文本，不发送图片或附件。保存不会调用外部服务。</el-alert><el-form-item label="决策 API Key" style="margin-top:18px"><el-input v-model="form.decision_api_key" type="password" show-password autocomplete="new-password" maxlength="4096" placeholder="留空保留已有密钥"/></el-form-item><el-form-item label="清除密钥"><el-checkbox v-model="form.clear_decision_key" :disabled="!!form.decision_api_key">清除已保存的密钥（启用前必须重新配置）</el-checkbox></el-form-item><el-form-item label="模型测试"><div><el-button type="primary" plain :loading="modelTesting" :disabled="form.clear_decision_key||saving" @click="testDecisionModel">测试模型</el-button><p class="field-help">使用当前地址及密钥；留空使用该供应商已保存密钥。仅验证连通性与响应格式，分类准确性请使用决策预览。</p><el-alert v-if="modelTestResult" :type="modelTestResult.available?'success':'error'" :title="modelTestResult.message" :closable="false" show-icon><span v-if="modelTestResult.elapsed_ms!=null">耗时 {{modelTestResult.elapsed_ms}} ms · </span><span v-if="modelTestResult.upstream_status">上游 HTTP {{modelTestResult.upstream_status}} · </span>{{modelTestResult.model}} <el-button v-if="modelTestResult.request_id" link type="primary" @click="router.push({path:'/admin/call-logs',query:{request_id:modelTestResult.request_id}})">调用日志</el-button></el-alert></div></el-form-item><el-form-item label="兜底模型组"><el-select v-model="form.decision_fallback_group" filterable><el-option v-for="g in groups" :key="g.id" :value="g.id" :label="g.name" :disabled="g.status!=='enabled'||!['text','multimodal'].includes(g.protocol_type||'text')"/></el-select></el-form-item><el-form-item label="决策超时"><el-input-number v-model="form.decision_timeout" :min="1" :max="60"/> 秒</el-form-item><el-form-item label="置信度下限"><el-input-number v-model="form.decision_threshold" :min="0" :max="1" :step=".05" :precision="2"/><p class="field-help">范围 0–1，低于此值转兜底组；与本地 / 向量模式的分类置信差相互独立。</p></el-form-item><el-alert type="info" :closable="false" show-icon title="模型决策的判断依据"><p>将请求中的用户文本与下方每个目标的名称、适用说明、排除说明交给决策模型分类。模型返回选择、目标概率分布及独立置信度；置信度达到下限才使用命中目标。选择“其他”、置信度不足或服务异常时转兜底组，权限、合规及配额拒绝不绕过。</p><p>本模式不使用向量样本、Top K、相似度或分类置信差。概率与置信度不是同一指标，也不是准确率保证；不要将模型分类用于权限或安全边界，用户文本可能干扰分类。请提供清晰、互斥且覆盖日常请求的说明，并用代表性及边界问题预览。</p></el-alert><div class="decision-target-header"><strong>路由目标（2–10 个）</strong><el-button :disabled="form.decision_targets.length>=10" @click="form.decision_targets.push({name:'',model_group_id:null,description:'',exclusion:''})">添加目标</el-button></div><div v-for="(target,index) in form.decision_targets" :key="index" class="decision-target"><div class="decision-target-header"><strong>目标 {{index+1}}</strong><el-button link type="danger" @click="form.decision_targets.splice(index,1)">移除</el-button></div><el-form-item label="目标名称"><el-input v-model="target.name" maxlength="80" placeholder="如：代码分析"/></el-form-item><el-form-item label="关联模型组"><el-select v-model="target.model_group_id" filterable><el-option v-for="g in groups" :key="g.id" :value="g.id" :label="g.name" :disabled="g.status!=='enabled'||!['text','multimodal'].includes(g.protocol_type||'text')"/></el-select></el-form-item><el-form-item label="适用说明"><el-input v-model="target.description" type="textarea" :rows="2" maxlength="1000" placeholder="说明哪些请求应使用此目标"/></el-form-item><el-form-item label="排除说明"><el-input v-model="target.exclusion" type="textarea" :rows="2" maxlength="1000" placeholder="可选：不适用的请求或相邻类别"/></el-form-item></div></template><el-form-item label="状态"><el-select v-model="form.status"><el-option label="禁用" value="disabled"/><el-option label="启用" value="enabled"/></el-select></el-form-item>
<p class="muted">{{editorMode==='model'?'模型决策：授权虚拟模型、全部目标组和兜底组；客户端请求先检查内容合规，再请求决策。':'本地 / 向量：'}}目标组须启用、有可用文本映射且不含虚拟模型。{{editorMode==='vector'?'未命中样本或置信差不足时转简单任务组；失败策略用于向量服务异常。':'模型决策异常、低置信度或其他目标转兜底组；安全与配额拒绝不绕过。'}}保存后将虚拟模型加入独立模型组，再授权给用户组。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer>
<el-dialog v-model="sampleDialog" :title="sampleEditing?'编辑样本':'新增样本'" width="620px"><el-form label-width="80px"><el-form-item label="样本文本"><el-input v-model="sample.prompt" type="textarea" :rows="6" maxlength="65536" show-word-limit/></el-form-item><el-form-item label="标签"><el-select v-model="sample.classification"><el-option label="简单任务" value="simple"/><el-option label="复杂任务" value="complex"/></el-select></el-form-item><el-form-item label="单样本阈值"><el-input-number v-model="sample.similarity_threshold" :min="0" :max="1" :step=".05" :precision="2" placeholder="继承规则阈值"/><el-button text @click="sample.similarity_threshold=null">继承规则</el-button></el-form-item><el-form-item label="备注"><el-input v-model="sample.remark" type="textarea" maxlength="2000"/></el-form-item><el-checkbox v-model="sample.build_vector">保存后生成向量</el-checkbox><p class="muted">构建向量可能产生上游用量。未构建的样本不参与匹配。</p></el-form><template #footer><el-button @click="sampleDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="sampleSave">保存</el-button></template></el-dialog>
<el-dialog v-model="importDialog" title="批量添加样本" width="700px"><el-radio-group v-model="bulkMode"><el-radio-button value="text">按行添加</el-radio-button><el-radio-button value="csv">CSV导入</el-radio-button></el-radio-group><el-form v-if="bulkMode==='text'" label-width="100px" style="margin-top:20px"><el-form-item label="标签"><el-select v-model="bulkLabel"><el-option label="简单任务" value="simple"/><el-option label="复杂任务" value="complex"/></el-select></el-form-item><el-form-item label="样本文本"><el-input v-model="bulkText" type="textarea" :rows="10" maxlength="2000000" placeholder="每行一条样本，每批最多500条；多行样本可使用CSV导入"/></el-form-item><el-form-item label="单样本阈值"><el-input-number v-model="bulkThreshold" :min="0" :max="1" :step=".05" :precision="2" placeholder="继承规则阈值"/><el-button text @click="bulkThreshold=null">继承规则</el-button></el-form-item><el-form-item label="备注"><el-input v-model="bulkRemark" maxlength="2000"/></el-form-item></el-form><template v-else><p class="muted">UTF-8 CSV，必需prompt,classification，可选similarity_threshold,remark；类别为simple或complex。每批最多500条、2MB，重复或错误拒绝整批。</p><input type="file" accept=".csv,text/csv" aria-label="选择CSV文件" @change="file"/><el-input v-model="csv" type="textarea" :rows="10" style="margin-top:16px"/></template><el-checkbox v-model="buildCSV" style="margin-top:16px">保存后生成向量</el-checkbox><p class="muted">未勾选时不请求上游；构建向量可能产生用量。</p><template #footer><el-button @click="importDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="bulkSave">保存</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" title="模型选择决策详情" size="900px" @close="detail=null"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="Request ID">{{detail.request_id}}</el-descriptions-item><el-descriptions-item label="决策时间">{{formatDate(detail.created_at)}}</el-descriptions-item><el-descriptions-item label="标签">{{detail.decision_target||labels[detail.classification]||'未分类'}}</el-descriptions-item><el-descriptions-item label="决策来源">{{sources[detail.source]||'历史未记录'}}</el-descriptions-item><el-descriptions-item label="虚拟模型">{{detail.virtual_model}}</el-descriptions-item><el-descriptions-item label="选中模型">{{detail.selected_model||'未选择'}}</el-descriptions-item><el-descriptions-item label="模型组">{{detail.selected_group_name||'未选择'}} (#{{detail.selected_model_group??'—'}})</el-descriptions-item><el-descriptions-item label="请求类型">{{detail.request_kind==='preview'?'决策预览':'真实请求'}} · {{detail.operation||'—'}}</el-descriptions-item><el-descriptions-item v-if="detail.source!=='model'" label="最高相似度">{{score(detail.similarity)}}</el-descriptions-item><el-descriptions-item :label="detail.source==='model'?'决策置信度':'实际分类置信差'">{{score(detail.confidence)}}</el-descriptions-item><el-descriptions-item label="决策耗时">{{detail.elapsed_ms}} ms</el-descriptions-item><el-descriptions-item label="决策状态">{{labels[detail.status]}}</el-descriptions-item><el-descriptions-item label="判定原因" :span="2">{{reasonText(detail.reason)}}</el-descriptions-item><el-descriptions-item label="规范化请求文本" :span="2"><pre class="selection-text">{{detail.normalized_text??'历史日志未记录请求文本'}}</pre></el-descriptions-item></el-descriptions><p v-if="detail.source==='model'" class="muted">本次决策置信度下限：{{score(detail.evidence?.[0]?.threshold)}}。概率与置信度独立；“其他”或置信度不足会转兜底。下方说明保存为当时快照，配置修改不改变历史依据；旧日志可能缺失。</p><p v-if="detail.source!=='model'" class="muted">分类置信差为最高类别与另一类别的相似度差，独立于最高相似度，不表示概率；历史字段未记录时显示缺失。</p><router-link v-if="detail.request_kind!=='preview'" class="route-link" :to="'/admin/call-logs/'+detail.request_id">查看实际调用日志 →</router-link><p v-if="detail.embedding_request_id"><router-link class="route-link" :to="'/admin/call-logs/'+detail.embedding_request_id">查看向量子调用 →</router-link></p><p v-if="detail.decision_model">决策模型：{{decisionProviderName(detail.decision_model)}} / {{detail.decision_model}} <router-link v-if="detail.decision_request_id" :to="'/admin/call-logs/'+detail.decision_request_id">查看决策子调用 →</router-link></p><h3>{{detail.source==='model'?'目标概率分布':'Top K 命中样本'}}</h3><el-table v-if="detail.source==='model'" :data="detail.evidence"><el-table-column type="expand"><template #default="s"><p>适用说明：{{s.row.description||'历史未记录'}}</p><p>排除说明：{{s.row.exclusion||'无额外排除说明'}}</p></template></el-table-column><el-table-column prop="target" label="路由目标" min-width="160"/><el-table-column label="模型选择" width="100"><template #default="s">{{s.row.selected===true?'选中':s.row.selected===false?'—':'未记录'}}</template></el-table-column><el-table-column label="概率"><template #default="s">{{score(s.row.probability)}}</template></el-table-column></el-table><el-table v-if="detail.source!=='model'" :data="detail.evidence" empty-text="未取得有效检索证据"><el-table-column prop="sample_id" label="样本ID" width="90"/><el-table-column label="标签" width="110"><template #default="s">{{labels[s.row.classification]}}</template></el-table-column><el-table-column prop="sample_text" label="样本文本" min-width="220" show-overflow-tooltip/><el-table-column label="相似度" width="110"><template #default="s">{{score(s.row.similarity)}}</template></el-table-column><el-table-column label="生效阈值" width="110"><template #default="s">{{score(s.row.effective_threshold??s.row.similarity_threshold)}}</template></el-table-column><el-table-column label="判定作用" width="110"><template #default="s">{{s.row.effective_threshold==null?'历史未记录':s.row.similarity>=s.row.effective_threshold?'达到阈值':'低于阈值'}}</template></el-table-column></el-table><p v-if="detail.source!=='model'" class="muted">命中样本保存当时文本摘要与阈值快照，样本编辑或删除不会改变历史证据。</p></template></el-drawer>
</div></template>
<style scoped>.route-link{color:var(--el-color-primary)}.route-cards{display:flex;gap:18px;margin:20px 0}.route-cards>div{flex:1;padding:20px;background:var(--soft);border-radius:8px;color:var(--muted)}.route-cards strong{display:block;font-size:28px;color:var(--text);margin-top:12px}</style>



<style scoped>.route-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}@media(min-width:1500px){.route-cards{grid-template-columns:repeat(6,minmax(0,1fr))}}@media(max-width:650px){.route-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>

<style scoped>.selection-text{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;margin:0;font:inherit}</style>

<style scoped>.vector-state{display:flex;flex-direction:column;align-items:flex-start;gap:7px;min-width:0;padding:3px 0}.vector-state-tag{flex-shrink:0}.vector-state-tag :deep(.el-tag__content){display:inline-flex;align-items:center;gap:6px}.vector-state-dot{width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0}.vector-state-dot.is-active{animation:vector-pulse 1.5s ease-in-out infinite}.vector-state-log{display:inline-flex;align-items:center;gap:5px;font-size:12px;line-height:18px;color:var(--el-color-primary);text-decoration:none;white-space:nowrap}.vector-state-log:hover{text-decoration:underline}.vector-state-log:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:3px;border-radius:3px}.vector-state-error{max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;line-height:18px;color:var(--el-color-danger)}@keyframes vector-pulse{50%{opacity:.35}}@media(prefers-reduced-motion:reduce){.vector-state-dot.is-active{animation:none}}</style>

<style scoped>.setup-mode{padding:16px 18px;background:var(--el-fill-color-light);border-radius:8px;margin:16px 0}.setup-mode p,.field-help{font-size:12px;line-height:1.7;color:var(--el-text-color-secondary);margin:6px 0 0}.setup-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:22px 0 16px}.setup-heading h2{font-size:16px;margin:0}.setup-heading p{margin:6px 0 0}.setup-note{margin-top:20px}.field-help{width:100%}</style>

<style scoped>.decision-target-header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0}.decision-target{border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:0 16px 6px;margin:14px 0}</style>

<style scoped>.decision-endpoint{overflow-wrap:anywhere;margin-bottom:16px}</style>
